+  <script>
+    // Tracks time the page is visible (foreground), in milliseconds.
+    const foregroundTracker = (() => {
+      let accumulated = 0;
+      let visibleSince = document.visibilityState === 'visible' ? performance.now() : null;
+
+      document.addEventListener('visibilitychange', () => {
+        if (document.visibilityState === 'visible') {
+          if (visibleSince === null) visibleSince = performance.now();
+        } else if (visibleSince !== null) {
+          accumulated += performance.now() - visibleSince;
+          visibleSince = null;
+        }
+      });
+
+      return {
+        getTotalForegroundTime() {
+          return accumulated + (visibleSince !== null ? performance.now() - visibleSince : 0);
+        }
+      };
+    })();
+
+    // Total foreground time in milliseconds.
+    function getTotalForegroundTime() {
+      return foregroundTracker.getTotalForegroundTime();
+    }
+  </script>
+
