+'use strict';
+// Minimal WebAuthn (passkey) verification using only node:crypto.
+// Supports "none" attestation and ES256 / RS256 / EdDSA credentials.
+const crypto = require('node:crypto');
+
+const b64u = {
+  encode: (buf) => Buffer.from(buf).toString('base64url'),
+  decode: (str) => Buffer.from(String(str), 'base64url'),
+};
+const sha256 = (data) => crypto.createHash('sha256').update(data).digest();
+
+// ---- Minimal CBOR decoder (definite lengths only) ----
+function cborDecode(buf, offset = 0) {
+  const major = buf[offset] >> 5;
+  const info = buf[offset] & 0x1f;
+  let pos = offset + 1;
+  let arg = info;
+  if (info === 24) { arg = buf[pos]; pos += 1; }
+  else if (info === 25) { arg = buf.readUInt16BE(pos); pos += 2; }
+  else if (info === 26) { arg = buf.readUInt32BE(pos); pos += 4; }
+  else if (info === 27) { arg = Number(buf.readBigUInt64BE(pos)); pos += 8; }
+  else if (info > 27) throw new Error('Unsupported CBOR encoding');
+
+  switch (major) {
+    case 0: return [arg, pos];
+    case 1: return [-1 - arg, pos];
+    case 2: return [buf.subarray(pos, pos + arg), pos + arg];
+    case 3: return [buf.toString('utf8', pos, pos + arg), pos + arg];
+    case 4: {
+      const arr = [];
+      for (let i = 0; i < arg; i++) { const [v, p] = cborDecode(buf, pos); arr.push(v); pos = p; }
+      return [arr, pos];
+    }
+    case 5: {
+      const map = new Map();
+      for (let i = 0; i < arg; i++) {
+        const [k, p1] = cborDecode(buf, pos);
+        const [v, p2] = cborDecode(buf, p1);
+        map.set(k, v); pos = p2;
+      }
+      return [map, pos];
+    }
+    case 7:
+      if (info === 20) return [false, pos];
+      if (info === 21) return [true, pos];
+      if (info === 22) return [null, pos];
+      throw new Error('Unsupported CBOR simple value');
+    default: throw new Error('Unsupported CBOR type');
+  }
+}
+
+function parseAuthData(authData) {
+  if (authData.length < 37) throw new Error('authData too short');
+  const flags = authData[32];
+  const out = {
+    rpIdHash: authData.subarray(0, 32),
+    userPresent: !!(flags & 0x01),
+    userVerified: !!(flags & 0x04),
+    backupEligible: !!(flags & 0x08),
+    backedUp: !!(flags & 0x10),
+    counter: authData.readUInt32BE(33),
+  };
+  if (flags & 0x40) {
+    const idLen = authData.readUInt16BE(53);
+    out.aaguid = authData.subarray(37, 53);
+    out.credentialId = authData.subarray(55, 55 + idLen);
+    const [cose] = cborDecode(authData, 55 + idLen);
+    out.cose = cose;
+  }
+  return out;
+}
+
+function coseToJwk(cose) {
+  const alg = cose.get(3);
+  if (alg === -7 && cose.get(1) === 2 && cose.get(-1) === 1) {
+    return { alg, jwk: { kty: 'EC', crv: 'P-256', x: b64u.encode(cose.get(-2)), y: b64u.encode(cose.get(-3)) } };
+  }
+  if (alg === -8 && cose.get(1) === 1 && cose.get(-1) === 6) {
+    return { alg, jwk: { kty: 'OKP', crv: 'Ed25519', x: b64u.encode(cose.get(-2)) } };
+  }
+  if (alg === -257 && cose.get(1) === 3) {
+    return { alg, jwk: { kty: 'RSA', n: b64u.encode(cose.get(-1)), e: b64u.encode(cose.get(-2)) } };
+  }
+  throw new Error('Unsupported credential algorithm');
+}
+
+function checkClientData(clientDataJSON, { type, challenge, origin }) {
+  const clientData = JSON.parse(clientDataJSON.toString('utf8'));
+  if (clientData.type !== type) throw new Error('Unexpected ceremony type');
+  if (clientData.challenge !== challenge) throw new Error('Challenge mismatch');
+  if (clientData.origin !== origin) throw new Error('Origin mismatch');
+  if (clientData.crossOrigin === true) throw new Error('Cross-origin ceremonies are not allowed');
+}
+
+function checkAuthData(a, rpId) {
+  if (!a.rpIdHash.equals(sha256(rpId))) throw new Error('RP ID mismatch');
+  if (!a.userPresent) throw new Error('User presence required');
+  if (!a.userVerified) throw new Error('User verification required');
+}
+
+/** Verify a registration response. Returns the credential record to store. */
+function verifyRegistration({ response, challenge, origin, rpId }) {
+  const clientDataJSON = b64u.decode(response.clientDataJSON);
+  checkClientData(clientDataJSON, { type: 'webauthn.create', challenge, origin });
+  const [att] = cborDecode(b64u.decode(response.attestationObject));
+  const authDataRaw = att.get('authData');
+  const a = parseAuthData(authDataRaw);
+  checkAuthData(a, rpId);
+  if (!a.cose) throw new Error('No credential data');
+  const { alg, jwk } = coseToJwk(a.cose);
+  return {
+    id: b64u.encode(a.credentialId),
+    publicKey: jwk,
+    alg,
+    counter: a.counter,
+    transports: Array.isArray(response.transports) ? response.transports.filter((t) => typeof t === 'string').slice(0, 8) : [],
+    backupEligible: a.backupEligible,
+    backedUp: a.backedUp,
+    aaguid: b64u.encode(a.aaguid),
+  };
+}
+
+/** Verify an assertion. Returns the new counter / backup state. Throws on failure. */
+function verifyAssertion({ response, challenge, origin, rpId, credential }) {
+  const clientDataJSON = b64u.decode(response.clientDataJSON);
+  checkClientData(clientDataJSON, { type: 'webauthn.get', challenge, origin });
+  const authData = b64u.decode(response.authenticatorData);
+  const a = parseAuthData(authData);
+  checkAuthData(a, rpId);
+  const key = crypto.createPublicKey({ key: credential.publicKey, format: 'jwk' });
+  const signed = Buffer.concat([authData, sha256(clientDataJSON)]);
+  const sig = b64u.decode(response.signature);
+  const ok = credential.alg === -8 ? crypto.verify(null, signed, key, sig) : crypto.verify('sha256', signed, key, sig);
+  if (!ok) throw new Error('Invalid signature');
+  if ((a.counter !== 0 || credential.counter !== 0) && a.counter <= credential.counter) {
+    throw new Error('Signature counter did not increase (possible cloned authenticator)');
+  }
+  return { counter: a.counter, backedUp: a.backedUp };
+}
+
+module.exports = { b64u, verifyRegistration, verifyAssertion };

